-- Sub-activity import for RISE Project Site Reports Hub
-- Generated 2026-09-07 from Progress_Calculation_Sheet_Monthly.xlsx
-- Only rows with a resolved task_code are inserted (unmatched leaves are listed in
-- sub_activities_mapping_report.md and excluded here).

create table if not exists project_schedule_sub_activities (
    id bigserial primary key,
    task_code text not null references project_schedule_activities(task_code) on delete cascade,
    name text not null,
    weight_factor numeric,
    unit_boq text,
    estimate_boq numeric,
    actual_boq numeric,
    poc_manual numeric,
    sort_order int,
    source_sheet text,
    source_row int,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now()
);

create index if not exists idx_project_schedule_sub_activities_task_code
    on project_schedule_sub_activities (task_code);

-- 741 rows (of 813 total leaf items; 72 unmatched, see report)
